"""
Caldera Bridge Engine for HTTP Terminator:
Translates zero-day and novel RFC protocol vulnerabilities discovered by Terminator
into non-MITRE Caldera Abilities, Adversaries, and Operations for fleet-wide replay,
continuous validation, and defender measurement.
"""

import hashlib
import json
import os
import re
import shutil
import sqlite3
import urllib.error
import urllib.request
import uuid
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple, Union

import yaml

from engine.taxonomy import ImpactClass, AnomalyCategory, ReproducibleVulnerability, NovelTechnique


# Non-MITRE Protocol Taxonomy Mapping for Caldera
TACTIC_MAP = {
    "QUEUE_POISONING": "queue-poisoning",
    "DESYNCHRONIZATION": "protocol-framing",
    "METAMORPHIC_VIOLATION": "metamorphic-divergence",
    "PARSER_CONFUSION": "parser-differential",
    "PARSER_DIVERGENCE": "parser-differential",
    "REQUEST_SMUGGLING": "protocol-framing",
    "CACHE_POISONING": "queue-poisoning",
    "BOUNDARY_OVERFLOW": "protocol-framing",
}

TECHNIQUE_MAP = {
    "RFC-9112": {
        "attack_id": "RFC-9112-DESYNC",
        "name": "HTTP/1.1 Message Framing & Pipeline Desynchronization",
    },
    "RFC-9113": {
        "attack_id": "RFC-9113-MULTIPLEX",
        "name": "HTTP/2 Stream Multiplexing & Pseudo-Header Confusion",
    },
    "RFC-8446": {
        "attack_id": "RFC-8446-KEYSHARE",
        "name": "TLS 1.3 KeyShare Negotiation & Early-Data Divergence",
    },
    "DEFAULT": {
        "attack_id": "RFC-PROTOCOL-ANOMALY",
        "name": "Autonomous RFC Protocol Invariant Violation",
    },
}


class CalderaBridge:
    """
    Bridges HTTP Terminator research findings into Caldera adversary emulation entities.
    Decoupled from standard MITRE ATT&CK enterprise matrices.
    """

    def __init__(self, db_path: str = "terminator.db"):
        self.db_path = Path(db_path)

    def _resolve_rfc_tag(self, text: str) -> str:
        """Extracts RFC identifier from text if present, else DEFAULT."""
        match = re.search(r"RFC[-\s]?(\d{4})", text, re.IGNORECASE)
        if match:
            return f"RFC-{match.group(1)}"
        return "DEFAULT"

    def generate_ability(
        self,
        finding_data: Dict[str, Any],
        ability_id: Optional[str] = None,
    ) -> Dict[str, Any]:
        """
        Converts a finding (from terminator.db or taxonomy object) into a
        Caldera-compliant Ability dictionary.
        """
        vuln_id = str(finding_data.get("vuln_id") or finding_data.get("eval_id") or uuid.uuid4())
        minimized_probe = finding_data.get("minimized_probe") or finding_data.get("raw_request") or ""

        if isinstance(minimized_probe, str):
            probe_bytes = minimized_probe.encode("latin-1", errors="replace")
        elif isinstance(minimized_probe, bytes):
            probe_bytes = minimized_probe
        else:
            probe_bytes = str(minimized_probe).encode("latin-1")

        payload_hex = probe_bytes.hex()
        probe_hash = hashlib.sha256(probe_bytes).hexdigest()[:8]

        ab_id = ability_id or f"terminator-{vuln_id.lower().replace('_', '-')}-{probe_hash}"

        impact = str(finding_data.get("impact") or finding_data.get("desync_class") or "DESYNCHRONIZATION").upper()
        tactic = TACTIC_MAP.get(impact, "protocol-framing")

        rationale = finding_data.get("rationale") or finding_data.get("details") or "Novel protocol flaw"
        rfc_tag = self._resolve_rfc_tag(rationale + " " + str(finding_data.get("rfc_fragment", "")))
        tech_meta = TECHNIQUE_MAP.get(rfc_tag, TECHNIQUE_MAP["DEFAULT"])

        name = f"{tech_meta['attack_id']}: {vuln_id}"
        description = (
            f"Autonomous RFC protocol validation probe generated by HTTP Terminator.\n"
            f"Impact: {impact}\n"
            f"Rationale: {rationale}\n"
            f"Probe SHA256: {hashlib.sha256(probe_bytes).hexdigest()}"
        )

        linux_cmd = (
            f"python3 terminator_runner.py "
            f"--target #{{target.host}} "
            f"--port #{{target.port}} "
            f"#{{target.tls_flag}} "
            f"--mode kettle_ab "
            f"--payload-hex {payload_hex}"
        )

        windows_cmd = (
            f"python terminator_runner.py "
            f"--target #{{target.host}} "
            f"--port #{{target.port}} "
            f"#{{target.tls_flag}} "
            f"--mode kettle_ab "
            f"--payload-hex {payload_hex}"
        )

        ability = {
            "id": ab_id,
            "name": name,
            "description": description,
            "tactic": tactic,
            "technique": {
                "attack_id": tech_meta["attack_id"],
                "name": tech_meta["name"],
            },
            "platforms": {
                "linux": {
                    "sh": {
                        "command": linux_cmd,
                        "payloads": ["terminator_runner.py"],
                        "timeout": 30,
                    }
                },
                "darwin": {
                    "sh": {
                        "command": linux_cmd,
                        "payloads": ["terminator_runner.py"],
                        "timeout": 30,
                    }
                },
                "windows": {
                    "psh": {
                        "command": windows_cmd,
                        "payloads": ["terminator_runner.py"],
                        "timeout": 30,
                    },
                    "cmd": {
                        "command": windows_cmd,
                        "payloads": ["terminator_runner.py"],
                        "timeout": 30,
                    },
                },
            },
            "singleton": True,
            "repeatable": False,
        }

        return ability

    def generate_adversary(
        self,
        abilities: List[Dict[str, Any]],
        adversary_id: Optional[str] = None,
        name: Optional[str] = None,
        description: Optional[str] = None,
    ) -> Dict[str, Any]:
        """
        Creates a Caldera Adversary profile that orders the protocol abilities.
        """
        adv_id = adversary_id or f"adversary-terminator-rfc-audit-{uuid.uuid4().hex[:6]}"
        adv_name = name or "HTTP Terminator RFC Protocol Flaw Replay"
        adv_desc = description or "Orchestrates replay of novel RFC protocol anomalies and framing violations."

        atomic_ordering = [ab["id"] for ab in abilities if "id" in ab]

        return {
            "id": adv_id,
            "name": adv_name,
            "description": adv_desc,
            "atomic_ordering": atomic_ordering,
            "tags": ["rfc-terminator", "non-mitre", "protocol-security"],
        }

    def fetch_confirmed_findings_from_db(self) -> List[Dict[str, Any]]:
        """Queries terminator.db for confirmed reproducible vulnerabilities."""
        if not self.db_path.exists():
            return []

        conn = sqlite3.connect(str(self.db_path))
        conn.row_factory = sqlite3.Row
        findings = []
        try:
            # 1. Query reproducible_vulnerabilities if populated
            cursor = conn.cursor()
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='reproducible_vulnerabilities'")
            if cursor.fetchone():
                cursor.execute(
                    """
                    SELECT vuln_id, anomaly_id, impact, minimized_probe, reproducibility_rate, provenance_chain
                    FROM reproducible_vulnerabilities
                    WHERE reproducibility_rate >= 0.5
                    """
                )
                for r in cursor.fetchall():
                    findings.append({
                        "vuln_id": r["vuln_id"],
                        "impact": r["impact"],
                        "minimized_probe": r["minimized_probe"],
                        "details": f"Reproducible Vulnerability (Rate: {r['reproducibility_rate'] * 100:.0f}%)",
                    })

            # 2. Query evaluations table for confirmed findings
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='evaluations'")
            if cursor.fetchone():
                cursor.execute(
                    """
                    SELECT e.eval_id, e.probe_id, e.target_host, e.desync_class, e.details,
                           p.rationale, p.raw_request
                    FROM evaluations e
                    JOIN probes p ON e.probe_id = p.probe_id
                    WHERE e.is_vulnerable = 1
                    """
                )
                for r in cursor.fetchall():
                    findings.append({
                        "eval_id": r["eval_id"],
                        "vuln_id": f"EVAL-{r['eval_id']}",
                        "impact": r["desync_class"] or "DESYNCHRONIZATION",
                        "raw_request": r["raw_request"],
                        "rationale": r["rationale"],
                        "details": r["details"],
                    })
        finally:
            conn.close()

        return findings

    def export_plugin(
        self,
        output_dir: str = "caldera_export",
        findings: Optional[List[Dict[str, Any]]] = None,
    ) -> Dict[str, Any]:
        """
        Exports a complete, ready-to-run Caldera plugin directory structure.
        """
        export_root = Path(output_dir)
        plugin_root = export_root / "plugins" / "terminator"

        abilities_dir = plugin_root / "data" / "abilities"
        adversaries_dir = plugin_root / "data" / "adversaries"
        payloads_dir = plugin_root / "payloads"
        app_dir = plugin_root / "app"

        for d in [abilities_dir, adversaries_dir, payloads_dir, app_dir]:
            d.mkdir(parents=True, exist_ok=True)

        # 1. Copy runner payload
        source_runner = Path(__file__).resolve().parent.parent / "payloads" / "terminator_runner.py"
        target_runner = payloads_dir / "terminator_runner.py"
        if source_runner.exists():
            shutil.copy2(source_runner, target_runner)
        else:
            # Fallback if running elsewhere
            payloads_dir.mkdir(parents=True, exist_ok=True)

        # 2. Ingest findings
        active_findings = findings if findings is not None else self.fetch_confirmed_findings_from_db()

        # If no active findings exist in DB yet, generate standard RFC-9112 and RFC-9113 baseline abilities
        if not active_findings:
            active_findings = [
                {
                    "vuln_id": "RFC-9112-DANGLING-BYTE",
                    "impact": "QUEUE_POISONING",
                    "raw_request": (
                        "POST / HTTP/1.1\r\n"
                        "Host: target.local\r\n"
                        "Content-Length: 6\r\n"
                        "Connection: keep-alive\r\n\r\n"
                        "12345"  # Missing 1 byte (dangling byte)
                    ),
                    "rationale": "RFC 9112 §6.1 dangling-byte probe to test proxy queue desynchronization",
                },
                {
                    "vuln_id": "RFC-9112-COLON-TAB-DESYNC",
                    "impact": "DESYNCHRONIZATION",
                    "raw_request": (
                        "GET / HTTP/1.1\r\n"
                        "Host: target.local\r\n"
                        "Transfer-Encoding :\tchunked\r\n"
                        "Connection: keep-alive\r\n\r\n"
                        "0\r\n\r\n"
                    ),
                    "rationale": "RFC 9112 §5.1 pre-colon whitespace and tab mutation",
                },
                {
                    "vuln_id": "RFC-9113-PSEUDO-HEADER-ORDER",
                    "impact": "PARSER_DIVERGENCE",
                    "raw_request": (
                        "GET / HTTP/1.1\r\n"
                        "Host: target.local\r\n"
                        "X-Forwarded-For: 127.0.0.1\r\n"
                        ":path: /\r\n\r\n"
                    ),
                    "rationale": "RFC 9113 §8.3 pseudo-header sequence confusion",
                },
            ]

        generated_abilities = []
        for f in active_findings:
            ability = self.generate_ability(f)
            generated_abilities.append(ability)

            # Group ability by tactic in caldera directory
            tactic_dir = abilities_dir / ability["tactic"]
            tactic_dir.mkdir(parents=True, exist_ok=True)
            ability_file = tactic_dir / f"{ability['id']}.yml"
            with open(ability_file, "w", encoding="utf-8") as out_f:
                yaml.dump([ability], out_f, sort_keys=False, default_flow_style=False)

        # 3. Generate Adversary Profile
        adversary = self.generate_adversary(
            generated_abilities,
            adversary_id="adversary-rfc-flaw-auditor",
            name="Autonomous RFC Protocol Flaw Replay",
            description="Continuous validation and replay of non-MITRE RFC protocol vulnerabilities discovered by HTTP Terminator.",
        )
        adv_file = adversaries_dir / "adversary-rfc-flaw-auditor.yml"
        with open(adv_file, "w", encoding="utf-8") as out_f:
            yaml.dump(adversary, out_f, sort_keys=False, default_flow_style=False)

        # 4. Generate hook.py
        hook_py = plugin_root / "hook.py"
        with open(hook_py, "w", encoding="utf-8") as out_f:
            out_f.write(self._generate_hook_py_content())

        # 5. Generate app/terminator_svc.py
        svc_py = app_dir / "terminator_svc.py"
        with open(svc_py, "w", encoding="utf-8") as out_f:
            out_f.write(self._generate_service_py_content())

        return {
            "status": "SUCCESS",
            "plugin_path": str(plugin_root),
            "abilities_count": len(generated_abilities),
            "adversaries_count": 1,
            "tactics": list(set(ab["tactic"] for ab in generated_abilities)),
        }

    def push_to_caldera(
        self,
        caldera_url: str,
        api_key: str,
        abilities: Optional[List[Dict[str, Any]]] = None,
        adversary: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """
        Pushes abilities and adversaries directly to a live Caldera server REST API (v2).
        """
        results: Dict[str, Any] = {"pushed_abilities": 0, "pushed_adversaries": 0, "errors": []}
        clean_url = caldera_url.rstrip("/")

        headers = {
            "KEY": api_key,
            "Content-Type": "application/json",
            "User-Agent": "HTTP-Terminator-Caldera-Bridge/1.0",
        }

        # 1. Push abilities
        if abilities:
            for ab in abilities:
                url = f"{clean_url}/api/v2/abilities"
                data = json.dumps(ab).encode("utf-8")
                req = urllib.request.Request(url, data=data, headers=headers, method="POST")
                try:
                    with urllib.request.urlopen(req, timeout=10.0) as resp:
                        if resp.status in (200, 201):
                            results["pushed_abilities"] += 1
                except urllib.error.HTTPError as e:
                    # If ability already exists, try PUT
                    if e.code == 409 or e.code == 400:
                        put_url = f"{clean_url}/api/v2/abilities/{ab['id']}"
                        put_req = urllib.request.Request(put_url, data=data, headers=headers, method="PUT")
                        try:
                            with urllib.request.urlopen(put_req, timeout=10.0) as put_resp:
                                if put_resp.status in (200, 204):
                                    results["pushed_abilities"] += 1
                        except Exception as put_e:
                            results["errors"].append(f"PUT {ab['id']}: {put_e}")
                    else:
                        results["errors"].append(f"POST {ab['id']}: {e}")
                except Exception as e:
                    results["errors"].append(f"POST {ab['id']}: {e}")

        # 2. Push adversary
        if adversary:
            url = f"{clean_url}/api/v2/adversaries"
            data = json.dumps(adversary).encode("utf-8")
            req = urllib.request.Request(url, data=data, headers=headers, method="POST")
            try:
                with urllib.request.urlopen(req, timeout=10.0) as resp:
                    if resp.status in (200, 201):
                        results["pushed_adversaries"] += 1
            except urllib.error.HTTPError as e:
                if e.code in (400, 409):
                    put_url = f"{clean_url}/api/v2/adversaries/{adversary['id']}"
                    put_req = urllib.request.Request(put_url, data=data, headers=headers, method="PUT")
                    try:
                        with urllib.request.urlopen(put_req, timeout=10.0) as put_resp:
                            if put_resp.status in (200, 204):
                                results["pushed_adversaries"] += 1
                    except Exception as put_e:
                        results["errors"].append(f"PUT adversary: {put_e}")
                else:
                    results["errors"].append(f"POST adversary: {e}")
            except Exception as e:
                results["errors"].append(f"POST adversary: {e}")

        return results

    def ingest_caldera_operation(
        self,
        operation_report: Dict[str, Any],
        world_model: Optional[Any] = None,
    ) -> Dict[str, Any]:
        """
        Parses results from a Caldera operation and extracts facts to feed back into
        Terminator's Dream-RSI World Model.
        """
        summary = {
            "operation_id": operation_report.get("id"),
            "host_count": 0,
            "vulnerabilities_confirmed": 0,
            "neutralized_count": 0,
            "facts_ingested": 0,
        }

        steps = operation_report.get("chain", []) or operation_report.get("steps", [])
        for step in steps:
            ability_id = step.get("ability", {}).get("ability_id") or step.get("ability_id", "")
            output_raw = step.get("output", "")
            status = step.get("status", 0)

            # Try parsing JSON output from terminator_runner
            parsed_output = {}
            if isinstance(output_raw, str):
                try:
                    parsed_output = json.loads(output_raw)
                except Exception:
                    pass

            is_vuln = parsed_output.get("desync_confirmed", False) or parsed_output.get("status") == "CONFIRMED_VULNERABILITY"
            if is_vuln:
                summary["vulnerabilities_confirmed"] += 1
            else:
                summary["neutralized_count"] += 1

            # If World Model provided, update its state
            if world_model and hasattr(world_model, "record_step"):
                probe_hex = step.get("command", "")
                # Extract hex from command string if present
                hex_match = re.search(r"--payload-hex\s+([0-9a-fA-F]+)", probe_hex)
                probe_bytes = bytes.fromhex(hex_match.group(1)) if hex_match else b"PROBE"
                world_model.record_step(
                    probe_bytes=probe_bytes,
                    status_code=parsed_output.get("baseline_status", 200) if isinstance(parsed_output.get("baseline_status"), int) else 200,
                    is_anomaly=bool(parsed_output.get("residual_leak", 0) > 0),
                    is_vulnerability=is_vuln,
                    details=f"Caldera Operation {summary['operation_id']} feedback",
                )
                summary["facts_ingested"] += 1

        return summary

